Use rolling-row dynamic programming: each cell adds its value to the smaller path cost from above or left, counting both endpoints.

```javascript
function solve(grid) {
  const columns = grid[0].length;
  const dp = new Array(columns).fill(Infinity);
  dp[0] = 0;

  for (const row of grid) {
    for (let col = 0; col < columns; col++) {
      const left = col > 0 ? dp[col - 1] : Infinity;
      dp[col] = row[col] + Math.min(dp[col], left);
    }
  }

  return dp[columns - 1];
}
```

